import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import { Request, Response } from 'express';
import multer from 'multer';
import pdfParse from 'pdf-parse';

export const upload = multer({ 
  storage: multer.memoryStorage(),
  limits: { fileSize: 5 * 1024 * 1024 },
  fileFilter: (req, file, cb) => {
    if (file.mimetype === 'application/pdf') {
      cb(null, true);
    } else {
      cb(new Error('Only PDF files are allowed'));
    }
  }
});

export async function analyzeResumeHandler(req: Request, res: Response): Promise<void> {
  try {
    if (!req.file) {
      res.status(400).json({ error: 'No PDF file uploaded' });
      return;
    }

    const { jobDescription } = req.body;
    if (!jobDescription) {
      res.status(400).json({ error: 'Job description is required' });
      return;
    }

    const pdfData = await pdfParse(req.file.buffer);
    const resumeText = pdfData.text;

    const cleanText = (text: string) => text.toLowerCase().replace(/[^a-z0-9\s]/g, '');
    const jdWords = Array.from(new Set(cleanText(jobDescription).split(/\s+/).filter(w => w.length > 3)));
    const resumeClean = cleanText(resumeText);

    const matchedKeywords: string[] = [];
    const missingKeywords: string[] = [];

    jdWords.forEach(word => {
      if (resumeClean.includes(word)) {
        matchedKeywords.push(word);
      } else {
        missingKeywords.push(word);
      }
    });

    const totalKeywords = jdWords.length || 1;
    const matchScore = Math.round((matchedKeywords.length / totalKeywords) * 100);

    res.status(200).json({
      matchScore,
      breakdown: {
        matched: matchedKeywords,
        missing: missingKeywords,
        totalAnalyzed: totalKeywords
      },
      extractedTextSnippet: resumeText.slice(0, 300) + '...'
    });
  } catch (error: any) {
    res.status(500).json({ error: error.message || 'Internal server error during resume parsing' });
  }
}

import React, { useState, ChangeEvent, FormEvent } from 'react';

interface AnalysisResult {
  matchScore: number;
  breakdown: {
    matched: string[];
    missing: string[];
    totalAnalyzed: number;
  };
  extractedTextSnippet: string;
}

export function MatchScoreDashboardView() {
  const [file, setFile] = useState<File | null>(null);
  const [jobDescription, setJobDescription] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<AnalysisResult | null>(null);

  const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
    }
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    if (!file || !jobDescription) return;

    setLoading(true);
    const formData = new FormData();
    formData.append('resume', file);
    formData.append('jobDescription', jobDescription);

    try {
      const response = await fetch('/api/analyze', {
        method: 'POST',
        body: formData,
      });
      const data = await response.json();
      setResult(data);
    } catch (err) {
      console.error('Failed to analyze resume', err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto p-6 bg-slate-900 text-slate-100 min-h-screen">
      <h1 className="text-3xl font-extrabold mb-6 text-indigo-400">AI Resume Keyword Scanner</h1>
      <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-6 bg-slate-800 p-6 rounded-xl shadow-lg">
        <div>
          <label className="block text-sm font-medium mb-2">Upload Resume (PDF)</label>
          <input type="file" accept=".pdf" onChange={handleFileChange} className="w-full text-slate-400 file:mr-4 file:py-2 file:px-4 file:rounded-lg file:border-0 file:text-sm file:font-semibold file:bg-indigo-600 file:text-white hover:file:bg-indigo-750" />
        </div>
        <div>
          <label className="block text-sm font-medium mb-2">Job Description</label>
          <textarea rows={4} value={jobDescription} onChange={(e) => setJobDescription(e.target.value)} placeholder="Paste target job description here..." className="w-full p-3 bg-slate-900 border border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500" />
        </div>
        <div className="md:col-span-2">
          <button type="submit" disabled={loading || !file || !jobDescription} className="w-full py-3 bg-indigo-600 hover:bg-indigo-500 disabled:bg-slate-700 rounded-lg font-bold transition-all duration-200">
            {loading ? 'Scanning & Parsing...' : 'Calculate Match Score'}
          </button>
        </div>
      </form>

      {result && (
        <div className="mt-8 bg-slate-800 p-6 rounded-xl shadow-lg">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-xl font-bold">Match Breakdown</h2>
            <div className="flex items-center space-x-2">
              <div className="text-3xl font-black text-indigo-400">{result.matchScore}%</div>
              <div className="text-sm text-slate-400">Match Score</div>
            </div>
          </div>
          <div className="w-full bg-slate-700 h-4 rounded-full overflow-hidden mb-6">
            <div className="bg-gradient-to-r from-indigo-500 to-emerald-400 h-full transition-all duration-1000" style={{ width: `${result.matchScore}%` }} />
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="bg-slate-900 p-4 rounded-lg">
              <h3 className="text-sm font-semibold text-emerald-400 mb-3">Matched Keywords ({result.breakdown.matched.length})</h3>
              <div className="flex flex-wrap gap-2">
                {result.breakdown.matched.map((kw, i) => (
                  <span key={i} className="px-2.5 py-1 bg-emerald-950 text-emerald-300 border border-emerald-800 rounded-md text-xs">{kw}</span>
                ))}
              </div>
            </div>
            <div className="bg-slate-900 p-4 rounded-lg">
              <h3 className="text-sm font-semibold text-rose-400 mb-3">Missing Keywords ({result.breakdown.missing.length})</h3>
              <div className="flex flex-wrap gap-2">
                {result.breakdown.missing.map((kw, i) => (
                  <span key={i} className="px-2.5 py-1 bg-rose-950 text-rose-300 border border-rose-800 rounded-md text-xs">{kw}</span>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
